import { DomainError } from "./domain-error";
import { mergeLines, OrderLine } from "./order-line";
import { isCancellable, nextFulfilmentStatus, OrderStatus } from "./order-status";

export class Order {
  private current: OrderStatus = "placed";
  readonly lines: readonly OrderLine[];

  constructor(
    readonly id: string,
    lines: readonly OrderLine[],
    readonly placedAt: Date,
  ) {
    if (lines.length === 0) {
      throw new DomainError("VALIDATION", "An order needs at least one line");
    }
    this.lines = mergeLines(lines);
  }

  get status(): OrderStatus {
    return this.current;
  }

  advanceTo(target: OrderStatus): void {
    if (nextFulfilmentStatus(this.current) !== target) {
      throw new DomainError(
        "INVALID_TRANSITION",
        `Order ${this.id} cannot move from ${this.current} to ${target}`,
      );
    }
    this.current = target;
  }

  cancel(): void {
    if (!isCancellable(this.current)) {
      throw new DomainError("INVALID_TRANSITION", `Order ${this.id} is ${this.current} and cannot be cancelled`);
    }
    this.current = "cancelled";
  }
}

