import { DomainError } from "./domain-error";

export class Product {
  private available: number;
  private reserved = 0;

  constructor(
    readonly id: string,
    readonly name: string,
    initialStock: number,
  ) {
    if (!Number.isInteger(initialStock) || initialStock < 0) {
      throw new DomainError("VALIDATION", "Stock must be a non-negative integer");
    }
    this.available = initialStock;
  }

  get availableQuantity(): number {
    return this.available;
  }

  get reservedQuantity(): number {
    return this.reserved;
  }

  reserve(quantity: number): void {
    if (quantity > this.available) {
      throw new DomainError(
        "INSUFFICIENT_STOCK",
        `Insufficient stock for product ${this.id}: requested ${quantity}, available ${this.available}`,
      );
    }
    this.available -= quantity;
    this.reserved += quantity;
  }

  release(quantity: number): void {
    const released = Math.min(quantity, this.reserved);
    this.reserved -= released;
    this.available += released;
  }
}

