import { DomainError } from "./domain-error";
import { OrderLine } from "./order-line";
import { Product } from "./product";
import { ProductRepository } from "./product-repository";

export class StockAllocationService {
  constructor(private readonly products: ProductRepository) {}

  reserve(lines: readonly OrderLine[]): void {
    const resolved = this.resolve(lines);
    for (const [line, product] of resolved) {
      if (line.quantity > product.availableQuantity) {
        throw new DomainError(
          "INSUFFICIENT_STOCK",
          `Insufficient stock for product ${product.id}: requested ${line.quantity}, available ${product.availableQuantity}`,
        );
      }
    }
    for (const [line, product] of resolved) {
      product.reserve(line.quantity);
      this.products.save(product);
    }
  }

  release(lines: readonly OrderLine[]): void {
    for (const [line, product] of this.resolve(lines)) {
      product.release(line.quantity);
      this.products.save(product);
    }
  }

  private resolve(lines: readonly OrderLine[]): Array<[OrderLine, Product]> {
    return lines.map((line) => {
      const product = this.products.findById(line.productId);
      if (!product) {
        throw new DomainError("NOT_FOUND", `Product ${line.productId} not found`);
      }
      return [line, product];
    });
  }
}

